/// <summary>
/// Data contract class as a response for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METBaseResponseContract
{
    String10        result; //string for enum METProcessingStatus
    ErrorMessage    message;

    // CB233_TOReceiptDetails
    String30        identifier;

}

Method.Source:
/// <summary>
/// Method returns true if sales order is cancelled/else false
/// </summary>
/// <param name = "_result">a boolean value indicating the sales cancellation result</param>
/// <returns>returns true if sales order is cancelled/else false</returns>
[DataMemberAttribute('Result')]
public String10 parmResult(String10 _result = result)
{
    result = _result;
    return result;
}

/// <summary>
/// This method returns the message corresponding to the sales order cancellation
/// </summary>
/// <param name = "_message">a string value specifying the sales cancellation result</param>
/// <returns>returns the message corresponding to the sales order cancellation</returns>
[DataMemberAttribute('Message')]
public ErrorMessage parmMessage(ErrorMessage _message = message)
{
    message = _message;
    return message;
}

/// <summary>
/// CB233_TOReceiptDetails
/// This method gets/sets the unique identifier in the custom service contract METBaseMultiResponseContract
/// </summary>
/// <param name = "_identifier">a string value specifying the unique identifier result</param>
/// <returns>returns unique identifier</returns>
[DataMemberAttribute('Identifier')]
public String30 parmIdentifier(String30 _identifier = identifier)
{
    identifier = _identifier;
    return identifier;
}

    /// <summary>
    /// CB233_TOReceiptDetails
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_identifier">Identifier</param>
    /// <param name = "_result">Result</param>
    /// <param name = "_message">Message Result</param>
    /// <returns>new base response contract</returns>
    public static METBaseResponseContract newFromParameters(String30 _identifier, METProcessingStatus _result, ErrorMessage _message)
    {
        METBaseResponseContract response = new METBaseResponseContract();

        response.parmIdentifier(_identifier);
        response.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        response.parmMessage(_message);

        return response;
    }
